  const periodEnd = new Date(report.period_end);

  const nextReportAt = new Date(
    periodEnd.getTime() + (7 * 24 * 60 * 60 * 1000)
  ).toISOString();

  const body = {
    last_report_at: periodEnd.toISOString(),
    next_report_at: nextReportAt
  };

  if (report.report_type === 'initial_historical') {
    body.initial_report_generated_at =
      $now.toUTC().toISO();
  }

  return body;
})() }}

