const client = $json;

if (!client.id) {
  throw new Error('معرف العميل غير موجود');
}

const dayMs = 24 * 60 * 60 * 1000;

let reportType;
let periodStart;
let periodEnd;

if (!client.initial_report_generated_at) {
  reportType = 'initial_historical';

  periodEnd = new Date();

  periodStart = new Date(
    periodEnd.getTime() - 30 * dayMs
  );
} else {
  reportType = 'weekly';

  periodStart = new Date(
    client.last_report_at ||
    client.activated_at || client.created_at || new Date(Date.now() - 7 * dayMs)
  );

  periodEnd = new Date(
    client.next_report_at ||
    new Date()
  );
}

return {
  json: {
    ...client,

    report_type: reportType,

    period_start:
      periodStart.toISOString(),

    period_end:
      periodEnd.toISOString()
  }
};

const context =
  $('Loop Platform Reports').last().json;

// إزالة العنصر الفارغ إن وجد
const feedback = $input.all()
  .map(item => item.json)
  .filter(item => item.source_record_id);

if (!feedback.length) {
  return [];
}

if (feedback.some(row => Number(row.client_id) !== Number(context.client_id) || Number(row.platform_id) !== Number(context.id) || (row.branch_id ?? null) !== (context.branch_id ?? null))) throw new Error('REPORT_FEEDBACK_SCOPE_MISMATCH');

const total = feedback.length;

const percent = value =>
  total > 0
    ? Number(((value / total) * 100).toFixed(2))
    : 0;

const sentimentCounts = {
  positive: 0,
  negative: 0,
  neutral: 0
};

const severityCounts = {
  low: 0,
  medium: 0,
  high: 0
};

const categoryCounts = {};
const negativeCategoryCounts = {};
const positiveCategoryCounts = {};

let needsReplyCount = 0;
let complaintsCount = 0;
let salesOpportunitiesCount = 0;

const ratings = [];

const normalizeCategories = value => {
  if (Array.isArray(value)) {
    return value;
  }

  if (!value) {
    return ['أخرى'];
  }

  return [String(value)];
};

for (const row of feedback) {
  const sentiment = [
    'positive',
    'negative',
    'neutral'
  ].includes(row.sentiment)
    ? row.sentiment
    : 'neutral';

  sentimentCounts[sentiment]++;

  const severity = [
    'low',
    'medium',
    'high'
  ].includes(row.severity)
    ? row.severity
    : 'low';

  severityCounts[severity]++;

  if (row.needs_reply === true) {
    needsReplyCount++;
  }

  if (row.is_complaint === true) {
    complaintsCount++;
  }

  if (row.is_sales_opportunity === true) {
    salesOpportunitiesCount++;
  }

  const rating = Number(row.rating);

  if (
    row.rating !== null &&
    row.rating !== undefined &&
    !Number.isNaN(rating)
  ) {
    ratings.push(rating);
  }

  const categories = normalizeCategories(
    row.category
  );

  for (const category of categories) {
    const name = String(category || 'أخرى');

    categoryCounts[name] =
      (categoryCounts[name] || 0) + 1;

    if (sentiment === 'negative') {
      negativeCategoryCounts[name] =
        (negativeCategoryCounts[name] || 0) + 1;
    }

    if (sentiment === 'positive') {
      positiveCategoryCounts[name] =
        (positiveCategoryCounts[name] || 0) + 1;
    }
  }
}

const sortCounts = counts =>
  Object.entries(counts)
    .sort((a, b) => b[1] - a[1])
    .map(([name, count]) => ({
      name,
      count
    }));

const averageRating = ratings.length
  ? Number(
      (
        ratings.reduce(
          (sum, value) => sum + value,
          0
        ) / ratings.length
      ).toFixed(2)
    )
  : null;

const urgentCases = feedback
  .filter(row =>
    ['high', 'critical'].includes(row.severity) && (row.sentiment === 'negative' || row.is_complaint === true)
  )
  .map(row => ({
    source_record_id: row.source_record_id,
    source_table: row.source_table,
    client_id: row.client_id,
    platform_id: row.platform_id,
    branch_id: row.branch_id ?? null,
    severity: row.severity,
    sentiment: row.sentiment,
    is_complaint: row.is_complaint === true,
    external_id: row.external_id || null,
    feedback_text: row.feedback_text || '',
    category: normalizeCategories(row.category),
    reason: row.reason || null,
    suggested_reply:
      row.suggested_reply || null,
    published_at: row.published_at || null
  }));

const feedbackForAi = feedback.map(row => ({
  source_record_id: row.source_record_id,
  feedback_text: row.feedback_text || '',
  rating: row.rating ?? null,
  sentiment: row.sentiment || 'neutral',
  category: normalizeCategories(row.category),
  severity: row.severity || 'low',
  needs_reply: row.needs_reply === true,
  is_complaint: row.is_complaint === true,
  is_sales_opportunity:
    row.is_sales_opportunity === true,
  reason: row.reason || null,
  published_at: row.published_at || null
}));

return [
  {
    json: {
      client_id: context.client_id,
      client_name: context.client_name || null,

      branch_id: context.branch_id ?? null,
      branch_name: context.branch_name || null,

      platform_id: context.id,
      platform_name: context.platform_name,

      report_scope: context.report_scope,
      report_type: context.report_type,

      period_start: context.period_start,
      period_end: context.period_end,

      stats: {
        total_feedback: total,

        sentiment: {
          positive: sentimentCounts.positive,
          negative: sentimentCounts.negative,
          neutral: sentimentCounts.neutral,

          positive_percentage:
            percent(sentimentCounts.positive),

          negative_percentage:
            percent(sentimentCounts.negative),

          neutral_percentage:
            percent(sentimentCounts.neutral)
        },

        severity: severityCounts,

        average_rating: averageRating,

        needs_reply_count:
          needsReplyCount,

        complaints_count:
          complaintsCount,

        sales_opportunities_count:
          salesOpportunitiesCount,

        categories:
          sortCounts(categoryCounts),

        top_issues:
          sortCounts(
            negativeCategoryCounts
          ).slice(0, 5),

        top_strengths:
          sortCounts(
            positiveCategoryCounts
          ).slice(0, 5),

        reputation_urgent_cases: urgentCases,

        urgent_cases_count:
          urgentCases.length
      },

      urgent_cases: urgentCases,
      feedback_for_ai: feedbackForAi
    }
  }
];

const client =
  $('Determine Report Period').last().json;

return $input.all().map(item => {
  const platform = item.json;

  const branch = Array.isArray(platform.branches)
    ? platform.branches[0]
    : platform.branches;

  return {
    json: {
      ...platform,

      client_name:
        client.name || null,

      report_type:
        client.report_type,

      period_start:
        client.period_start,

      period_end:
        client.period_end,

      branch_name:
        branch?.name || null,

      report_scope:
        platform.branch_id
          ? `${platform.platform_name}:branch:${platform.branch_id}`
          : `${platform.platform_name}:client`
    }
  };
});

return $input.all().filter(({ json: client }) => {
  const now = Date.now();
  const eligible = client.subscription_status === 'trial'
    ? Boolean(client.trial_ends_at) && Date.parse(client.trial_ends_at) > now
    : client.subscription_status === 'active' && (!client.current_period_end || Date.parse(client.current_period_end) > now);
  if (!eligible) return false;
  const dueAt = new Date(client.next_report_at || 0).getTime();
  const platforms = Array.isArray(client.client_platforms)
    ? client.client_platforms.filter(platform => platform.is_active === true)
    : [];

  return platforms.length > 0 && platforms.every(platform => {
    const completedAt = new Date(platform.last_success_at || 0).getTime();
    return Number.isFinite(completedAt) && completedAt >= dueAt;
  });
});
